    "about_text": "स्वे डिजिटल लैब एक स्वतंत्र डिजिटल स्टूडियो है जो सरल, उपयोगी और विचारशील डिजिटल उत्पाद बनाने पर केंद्रित है। हम विचारों का पता लगाते हैं, एप्लिकेशन बनाते हैं और अवधारणाओं को ऐसे टूल में बदलते हैं जो रोजमर्रा की जिंदगी को थोड़ा आसान बना सकते हैं।",
