    "screenshot_2_alt": "अंग्रेजी नाश्ता ऐप, फ्लैशकार्ड स्क्रीन: कार्ड, क्विज़, जोड़े और टेस्ट के लिए टैब, एक प्रगति लेबल \"सीखने में 1/10\", \"राष्ट्रपति\" शब्द और उसके उच्चारण, स्पीकर और पसंदीदा बटन वाला एक कार्ड, और नीचे जानें और जानें बटन।",
    "screenshot_4_alt": "इंग्लिश ब्रेकफास्ट ऐप, काउंटडाउन टाइमर के साथ साप्ताहिक लीग लीडरबोर्ड: 6,184 एक्सपी के साथ निक लिप के नेतृत्व में शीर्ष चार पोडियम, इसके बाद अवतार और एक्सपी स्कोर वाले खिलाड़ियों की एक रैंक सूची है।",
