    "about_text": "Sway Digital Lab は、シンプルで便利、思慮深いデジタル製品の作成に重点を置いた独立したデジタル スタジオです。私たちはアイデアを探求し、アプリケーションを構築し、コンセプトを日常生活を少し楽にするツールに変えます。",
    "page_meta_desc": "Sway Digital Lab は、イングリッシュ ブレックファストのような、焦点を絞った便利でシンプルなツールを作成する独立したデジタル スタジオです。",
